class Solution:
    def vowelStrings(self, words: List[str], left: int, right: int) -> int:
        vowels = set('aeiou')
        return sum(w[0] in vowels and w[-1] in vowels for w in words[left:right+1])

c.cpp:
class Solution {
public:
    int vowelStrings(vector<string>& words, int left, int right) {
        auto isVowel = [](char c) { return string("aeiou").find(c) != string::npos; };
        int cnt = 0;
        for (int i = left; i <= right; i++) {
            const string& w = words[i];
            if (isVowel(w.front()) && isVowel(w.back())) cnt++;
        }
        return cnt;
    }
};

c.java:
class Solution {
    public int vowelStrings(String[] words, int left, int right) {
        String v = "aeiou";
        int cnt = 0;
        for (int i = left; i <= right; i++) {
            String w = words[i];
            if (v.indexOf(w.charAt(0)) >= 0 && v.indexOf(w.charAt(w.length() - 1)) >= 0) cnt++;
        }
        return cnt;
    }
}

