var vowelStrings = function(words, left, right) {
    const v = new Set(['a','e','i','o','u']);
    let cnt = 0;
    for (let i = left; i <= right; i++) {
        const w = words[i];
        if (v.has(w[0]) && v.has(w[w.length - 1])) cnt++;
    }
    return cnt;
};
